import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert, Animated, Image, ImageBackground, KeyboardAvoidingView, Modal, PanResponder, Platform,
  Pressable, ScrollView, StyleSheet, Text, TextInput, View,
} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { SafeAreaView } from 'react-native-safe-area-context';
import DateTimePicker from '@react-native-community/datetimepicker';
import Slider from '@react-native-community/slider';
import * as ImagePicker from 'expo-image-picker';
import { Ionicons } from '@expo/vector-icons';
import { StatusBar } from 'expo-status-bar';

type Icon = React.ComponentProps<typeof Ionicons>['name'];
type Tab = 'Oversikt' | 'Budsjett' | 'Forsikringer' | 'Abonnement' | 'Sparing';
type Screen = Tab;
type GoalCategory = 'Sparemål' | 'Buffer' | 'Fond' | 'Aksjer' | 'Pensjon';
type FormKind = 'insurance' | 'subscription' | 'goal' | 'income' | 'expense' | null;
type Insurance = { id:string; type:string; provider:string; monthly:number; coverage:string; renewal:string; bonus?:string; coverageType?:string; insuredValue?:string; deductible?:string; startDate?:string; expiryDate?:string; note?:string };
type Subscription = { id:string; name:string; category:string; monthly:number; renewal:string };
type Goal = { id:string; name:string; target:number; saved:number; targetDate:string; category:GoalCategory; monthly:number; imageUri?:string };
type BudgetItem = { id:string; name:string; monthly:number; category:string; origin?:string; interest?:number; principal?:number };
type AppData = { insurance:Insurance[]; subscriptions:Subscription[]; goals:Goal[]; incomes:BudgetItem[]; expenses:BudgetItem[]; };
type BudgetRow = BudgetItem & { source:'income'|'manual'|'insurance'|'subscription'|'saving'; sourceId?:string };

const K='@oversiktsapp/v061';
const C={bg:'#EEE7D6',white:'#FFF',surface:'#F8F3E8',surfaceStrong:'#F3ECDE',ink:'#13231E',sub:'#66716C',muted:'#8A918E',green:'#0C624E',dark:'#173D32',pale:'#DDF3E9',icon:'#DCEAE4',line:'#D8D0C0',red:'#A8453C',redPale:'#FBEAE8',amber:'#95610F',amberPale:'#FFF3D7'};
const fmt=(n:number)=>new Intl.NumberFormat('nb-NO',{maximumFractionDigits:0}).format(Math.round(n));
const kr=(n:number)=>`${fmt(n)} kr`;
const num=(x='')=>{const n=Number(x.replace(/\s/g,'').replace(',','.').replace(/[^0-9.]/g,''));return Number.isFinite(n)?n:0};
const groupDigits=(x='')=>{const clean=x.replace(/\D/g,'');return clean?new Intl.NumberFormat('nb-NO',{maximumFractionDigits:0}).format(Number(clean)):''};
const uid=(p:string)=>`${p}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const dateText=(d:Date)=>new Intl.DateTimeFormat('nb-NO',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);
const parseDate=(x='')=>{const m=x.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/);return m?new Date(+m[3],+m[2]-1,+m[1]):null};
const insIcon=(x:string):Icon=>{x=x.toLowerCase();if(x.includes('bil'))return'car-sport-outline';if(x.includes('reise'))return'airplane-outline';if(x.includes('liv'))return'heart-outline';if(x.includes('helse')||x.includes('ulykke'))return'medical-outline';if(x.includes('dyr'))return'paw-outline';if(x.includes('hus')||x.includes('innbo'))return'home-outline';return'shield-outline'};
const subIcon=(x:string):Icon=>{x=x.toLowerCase();if(x.includes('musikk'))return'headset-outline';if(x.includes('telefon')||x.includes('mobil'))return'phone-portrait-outline';if(x.includes('film')||x.includes('tv')||x.includes('strøm'))return'play-circle-outline';if(x.includes('sky'))return'cloud-outline';if(x.includes('spill'))return'game-controller-outline';if(x.includes('avis'))return'newspaper-outline';if(x.includes('internett'))return'wifi-outline';return'globe-outline'};
const goalIcon=(g:Goal):Icon=>g.category==='Fond'||g.category==='Aksjer'?'trending-up-outline':g.category==='Pensjon'?'hourglass-outline':g.category==='Buffer'?'wallet-outline':g.name.toLowerCase().includes('tur')?'airplane-outline':'flag-outline';

const seed:AppData={
  incomes:[{id:'income-h',name:'Henrik netto lønn',monthly:37000,category:'Lønn',origin:'Arbeidsgiver'},{id:'income-s',name:'Sara netto lønn',monthly:40000,category:'Lønn',origin:'Arbeidsgiver'},{id:'income-study',name:'Studielån / utbetaling',monthly:8000,category:'Studielån',origin:'Lånekassen'}],
  expenses:[{id:'expense-home',name:'Bolig og lån',monthly:28924,category:'Bolig'},{id:'expense-food',name:'Mat og husholdning',monthly:11000,category:'Hverdag'},{id:'expense-child',name:'Barnehage',monthly:3136,category:'Barn'},{id:'expense-student',name:'Lånekassen',monthly:6500,category:'Gjeld'},{id:'expense-transport',name:'Transport',monthly:800,category:'Transport'}],
  insurance:[{id:'i1',type:'Hus og innbo',provider:'Eksempelselskap',monthly:1180,coverage:'Bygning og innbo',renewal:'01.05.2027'},{id:'i2',type:'Bilforsikring',provider:'Eksempelselskap',monthly:920,coverage:'Kasko',renewal:'15.03.2027'}],
  subscriptions:[{id:'s1',name:'Musikktjeneste',category:'Musikk',monthly:129,renewal:'15.11.2026'},{id:'s2',name:'Strømmetjeneste',category:'TV og underholdning',monthly:179,renewal:'01.11.2026'}],
  goals:[{id:'g1',name:'Sydentur 2030',target:80000,saved:12500,targetDate:'15.06.2030',category:'Sparemål',monthly:1000},{id:'g2',name:'Globalt indeksfond',target:500000,saved:45000,targetDate:'01.01.2040',category:'Fond',monthly:2500}],
};
const tabs:{name:Tab;icon:Icon}[]=[{name:'Oversikt',icon:'home-outline'},{name:'Budsjett',icon:'wallet-outline'},{name:'Forsikringer',icon:'shield-checkmark-outline'},{name:'Abonnement',icon:'repeat-outline'},{name:'Sparing',icon:'flag-outline'}];

export default function App(){
  const[tab,setTab]=useState<Tab>('Oversikt');
  const[screen,setScreen]=useState<Screen>('Oversikt');
  const[data,setData]=useState<AppData>(seed);
  const[ready,setReady]=useState(false);
  const[form,setForm]=useState<FormKind>(null);
  const[editId,setEditId]=useState<string|null>(null);
  const[undo,setUndo]=useState<{data:AppData;label:string}|null>(null);
  useEffect(()=>{(async()=>{try{const raw=await AsyncStorage.getItem(K);if(raw){const old=JSON.parse(raw);setData({...seed,...old,incomes:old.incomes||seed.incomes,expenses:old.expenses||seed.expenses,goals:(old.goals||seed.goals).map((g:Goal)=>({...g,monthly:g.monthly||0,category:g.category||'Sparemål'}))})}}finally{setReady(true)}})()},[]);
  useEffect(()=>{if(ready)AsyncStorage.setItem(K,JSON.stringify(data))},[data,ready]);
  const budget=useMemo(()=>{const baseRows:BudgetRow[]=[...data.expenses.map(x=>({...x,source:'manual' as const})),...data.insurance.map(x=>({id:`bi-${x.id}`,name:x.type,monthly:x.monthly,category:'Forsikringer',source:'insurance' as const,sourceId:x.id})),...data.subscriptions.map(x=>({id:`bs-${x.id}`,name:x.name,monthly:x.monthly,category:'Abonnement',source:'subscription' as const,sourceId:x.id}))];const rows=[...baseRows].sort((a,b)=>b.monthly-a.monthly);const savingRows:BudgetRow[]=data.goals.filter(x=>x.monthly>0).map(x=>({id:`bg-${x.id}`,name:x.name,monthly:x.monthly,category:x.category,source:'saving' as const,sourceId:x.id})).sort((a,b)=>b.monthly-a.monthly);const income=data.incomes.reduce((a,b)=>a+b.monthly,0);const expense=rows.reduce((a,b)=>a+b.monthly,0);const saving=savingRows.reduce((a,b)=>a+b.monthly,0);return{rows,savingRows,income,expense,saving,left:income-expense-saving}},[data]);
  const openAdd=(kind:Exclude<FormKind,null>)=>{setEditId(null);setForm(kind)};
  const openEdit=(kind:Exclude<FormKind,null>,id:string)=>{setEditId(id);setForm(kind)};
  const closeForm=()=>{setForm(null);setEditId(null)};
  const initialForm=useMemo(()=>{if(!form||!editId)return undefined;if(form==='income')return data.incomes.find(x=>x.id===editId);if(form==='expense')return data.expenses.find(x=>x.id===editId);if(form==='insurance')return data.insurance.find(x=>x.id===editId);if(form==='subscription')return data.subscriptions.find(x=>x.id===editId);if(form==='goal')return data.goals.find(x=>x.id===editId);return undefined},[form,editId,data]);
  const go=(t:Tab)=>{setTab(t);setScreen(t)};
  const snapshot=(label:string)=>setUndo({data:JSON.parse(JSON.stringify(data)),label});
  const remove=(kind:'insurance'|'subscription'|'goal',id:string,title:string)=>Alert.alert('Fjern post?',title,[{text:'Avbryt',style:'cancel'},{text:'Fjern',style:'destructive',onPress:()=>{snapshot(title);setData(d=>kind==='insurance'?{...d,insurance:d.insurance.filter(x=>x.id!==id)}:kind==='subscription'?{...d,subscriptions:d.subscriptions.filter(x=>x.id!==id)}:{...d,goals:d.goals.filter(x=>x.id!==id)})}}]);
  const deleteIncome=(id:string)=>{const item=data.incomes.find(x=>x.id===id);if(!item)return;Alert.alert('Fjern post?',item.category,[{text:'Avbryt',style:'cancel'},{text:'Fjern',style:'destructive',onPress:()=>{snapshot(item.category);setData(d=>({...d,incomes:d.incomes.filter(x=>x.id!==id)}))}}])};
  const deleteBudget=(row:BudgetRow)=>{if(row.source==='insurance')return remove('insurance',row.sourceId!,row.name);if(row.source==='subscription')return remove('subscription',row.sourceId!,row.name);if(row.source==='saving')return remove('goal',row.sourceId!,row.name);Alert.alert('Fjern post?',row.name,[{text:'Avbryt',style:'cancel'},{text:'Fjern',style:'destructive',onPress:()=>{snapshot(row.name);setData(d=>({...d,expenses:d.expenses.filter(x=>x.id!==row.id)}))}}])};
  const editIncome=(id:string)=>openEdit('income',id);
  const editExpense=(row:BudgetRow)=>{if(row.source==='insurance')return openEdit('insurance',row.sourceId!);if(row.source==='subscription')return openEdit('subscription',row.sourceId!);if(row.source==='saving')return openEdit('goal',row.sourceId!);openEdit('expense',row.id)};
  const saveIncome=(x:Omit<BudgetItem,'id'>)=>{setData(d=>({...d,incomes:editId?d.incomes.map(v=>v.id===editId?{...x,id:editId}:v):[...d.incomes,{...x,id:uid('in')}]}));closeForm()};
  const saveExpense=(x:Omit<BudgetItem,'id'>)=>{setData(d=>({...d,expenses:editId?d.expenses.map(v=>v.id===editId?{...x,id:editId}:v):[...d.expenses,{...x,id:uid('ex')}]}));closeForm()};
  const saveInsurance=(x:Omit<Insurance,'id'>)=>{setData(d=>({...d,insurance:editId?d.insurance.map(v=>v.id===editId?{...x,id:editId}:v):[...d.insurance,{...x,id:uid('i')}]}));closeForm()};
  const saveSubscription=(x:Omit<Subscription,'id'>)=>{setData(d=>({...d,subscriptions:editId?d.subscriptions.map(v=>v.id===editId?{...x,id:editId}:v):[...d.subscriptions,{...x,id:uid('s')}]}));closeForm()};
  const saveGoal=(x:Omit<Goal,'id'>)=>{setData(d=>({...d,goals:editId?d.goals.map(v=>v.id===editId?{...x,id:editId}:v):[...d.goals,{...x,id:uid('g')}]}));closeForm()};
  return <SafeAreaView style={S.safe}><StatusBar style="dark"/><View style={S.page}><Header title={screen}/><ScrollView contentContainerStyle={S.scroll} showsVerticalScrollIndicator={false}>
    {screen==='Oversikt'&&<Overview data={data} budget={budget} openBudget={()=>go('Budsjett')} go={go}/>} 
    {screen==='Budsjett'&&<BudgetView data={data} budget={budget} back={()=>setScreen('Oversikt')} addIncome={()=>openAdd('income')} addExpense={()=>openAdd('expense')} go={go} deleteIncome={deleteIncome} deleteExpense={deleteBudget} editIncome={editIncome} editExpense={editExpense}/>} 
    {screen==='Forsikringer'&&<InsuranceView items={data.insurance} add={()=>openAdd('insurance')} del={(i,t)=>remove('insurance',i,t)} edit={id=>openEdit('insurance',id)}/>} 
    {screen==='Sparing'&&<Savings goals={data.goals} add={()=>openAdd('goal')} del={(i,t)=>remove('goal',i,t)} edit={id=>openEdit('goal',id)} update={(i,n)=>setData(d=>({...d,goals:d.goals.map(g=>g.id===i?{...g,saved:Math.min(g.target,Math.max(0,g.saved+n))}:g)}))}/>} 
    {screen==='Abonnement'&&<Subscriptions items={data.subscriptions} add={()=>openAdd('subscription')} del={(i,t)=>remove('subscription',i,t)} edit={id=>openEdit('subscription',id)}/>} 
  </ScrollView><View pointerEvents="none" style={S.navMask}/><Nav active={tab} go={go}/><Form kind={form} initial={initialForm} editing={!!editId} close={closeForm} saveIncome={saveIncome} saveExpense={saveExpense} saveInsurance={saveInsurance} saveSubscription={saveSubscription} saveGoal={saveGoal}/>{undo&&<View style={S.undoBar}><Text style={S.undoText}>{undo.label} ble slettet</Text><Pressable onPress={()=>{setData(undo.data);setUndo(null)}} style={S.undoButton}><Text style={S.undoButtonText}>Angre</Text></Pressable><Pressable onPress={()=>setUndo(null)}><Ionicons name="close" size={18} color={C.white}/></Pressable></View>}</View></SafeAreaView>
}

function Header({title}:{title:string}){return <View style={S.header}><View><Text style={S.eyebrow}>OVERS</Text><Text style={S.title}>{title}</Text></View><View style={S.avatar}><Ionicons name="people" size={20} color={C.green}/></View></View>}
function Overview({data,budget,openBudget,go}:{data:AppData;budget:{income:number;expense:number;saving:number;left:number};openBudget:()=>void;go:(t:Tab)=>void}){const[all,setAll]=useState(false);return <><Pressable onPress={openBudget} style={S.hero}><Text style={S.heroLabel}>Penger til overs/mnd</Text><Text style={S.heroAmount}>{kr(budget.left)}</Text><View style={S.row}><Stat l="Inntekter" v={kr(budget.income)}/><Stat l="Utgifter" v={kr(budget.expense)}/><Stat l="Sparing" v={kr(budget.saving)}/></View><View style={S.heroLink}><Text style={S.heroLinkText}>Åpne budsjett</Text><Ionicons name="chevron-forward" size={18} color="#D9E8E2"/></View></Pressable><View style={S.pitch}><View style={S.icon}><Ionicons name="sparkles" size={23} color={C.green}/></View><View style={S.flex}><Text style={S.greenKicker}>NESTE ANBEFALING</Text><Text style={S.pitchTitle}>Se gjennom abonnementene</Text><Text style={S.small}>Du har {data.subscriptions.length} aktive abonnementer til {kr(data.subscriptions.reduce((a,b)=>a+b.monthly*12,0))} per år.</Text><Pressable onPress={()=>setAll(v=>!v)}><Text style={S.link}>{all?'Skjul rekkefølge':'Se anbefalt rekkefølge'}</Text></Pressable></View></View>{all&&<View style={S.infoCard}><Text style={S.cardTitle}>2. Sammenlign forsikringer</Text><Text style={S.cardTitle}>3. Bygg buffer</Text><Text style={S.cardTitle}>4. Finansier konkrete mål</Text><Text style={S.cardTitle}>5. Bygg langsiktig sparing</Text></View>}<Section title="Økonomien din"/><View style={S.monthGrid}><MonthMetric icon="wallet-outline" label="Til overs" value={kr(budget.left)}/><MonthMetric icon="flag-outline" label="Sparing" value={kr(budget.saving)}/><MonthMetric icon="shield-checkmark-outline" label="Forsikringer" value={kr(data.insurance.reduce((a,b)=>a+b.monthly,0))}/><MonthMetric icon="repeat-outline" label="Abonnement" value={kr(data.subscriptions.reduce((a,b)=>a+b.monthly,0))}/></View></>}

function BudgetView({data,budget,back,addIncome,addExpense,go,deleteIncome,deleteExpense,editIncome,editExpense}:{data:AppData;budget:{rows:BudgetRow[];savingRows:BudgetRow[];income:number;expense:number;saving:number;left:number};back:()=>void;addIncome:()=>void;addExpense:()=>void;go:(t:Tab)=>void;deleteIncome:(id:string)=>void;deleteExpense:(row:BudgetRow)=>void;editIncome:(id:string)=>void;editExpense:(row:BudgetRow)=>void}){
  const[open,setOpen]=useState<'income'|'expense'|'saving'|null>(null);
  return <>
    <BudgetHero label="INNTEKTER" value={budget.income} detail={`${data.incomes.length} registrerte inntekter`} color={C.dark} open={open==='income'} onPress={()=>setOpen(open==='income'?null:'income')} onAdd={open==='income'?addIncome:undefined}/>
    {open==='income'?<View style={S.accordion}>{[...data.incomes].sort((a,b)=>b.monthly-a.monthly).map(x=><GestureBudgetLine key={x.id} icon="arrow-down-circle-outline" name={x.category} sub={x.origin&&x.origin!=='Ikke oppgitt'?x.origin:''} value={x.monthly} onPress={()=>Alert.alert(x.category,`${x.origin&&x.origin!=='Ikke oppgitt'?`${x.origin}\n`:''}${kr(x.monthly)} per måned\n${kr(x.monthly*12)} per år`)} onEdit={()=>editIncome(x.id)} onDelete={()=>deleteIncome(x.id)}/>)}</View>:null}
    <BudgetHero label="UTGIFTER" value={budget.expense} detail={`${budget.rows.length} registrerte utgifter`} color={C.red} open={open==='expense'} onPress={()=>setOpen(open==='expense'?null:'expense')} onAdd={open==='expense'?addExpense:undefined}/>
    {open==='expense'?<View style={S.accordion}>{budget.rows.map(x=><GestureBudgetLine key={x.id} icon={x.source==='insurance'?'shield-checkmark-outline':x.source==='subscription'?'repeat-outline':'card-outline'} name={x.name} sub={x.source==='manual'?x.category:`Fra ${x.category}`} value={x.monthly} onPress={x.source==='insurance'?()=>go('Forsikringer'):x.source==='subscription'?()=>go('Abonnement'):()=>{const e=data.expenses.find(v=>v.id===x.id);Alert.alert(x.name,`${x.category}\n${kr(x.monthly)} per måned${e?.interest?`\nRenter: ${kr(e.interest)}`:''}${e?.principal?`\nAvdrag: ${kr(e.principal)}`:''}`)}} onEdit={()=>editExpense(x)} onDelete={()=>deleteExpense(x)}/>)}</View>:null}
    <BudgetHero label="SPARING" value={budget.saving} detail={`${budget.savingRows.length} faste spareposter`} color="#365F8D" open={open==='saving'} onPress={()=>setOpen(open==='saving'?null:'saving')} onAdd={open==='saving'?()=>go('Sparing'):undefined}/>
    {open==='saving'?<View style={S.accordion}>{budget.savingRows.map(x=><GestureBudgetLine key={x.id} icon="flag-outline" name={x.name} sub={`Fast sparing • ${x.category}`} value={x.monthly} onPress={()=>go('Sparing')} onEdit={()=>editExpense(x)} onDelete={()=>deleteExpense(x)}/>)}</View>:null}
    <BudgetHero label="PENGER TIL OVERS" value={budget.left} detail="Etter utgifter og fast sparing" color={budget.left>=0?C.dark:C.red} open={false}/>
    
    <View style={S.yearRow}><Text style={S.yearLabel}>Årlig inntekt</Text><Text style={S.yearValue}>{kr(budget.income*12)}</Text><Text style={S.yearLabel}>Årlige utgifter</Text><Text style={S.yearValue}>{kr(budget.expense*12)}</Text><Text style={S.yearLabel}>Årlig sparing</Text><Text style={S.yearValue}>{kr(budget.saving*12)}</Text></View>
  </>;
}
function BudgetHero({label,value,detail,color,open,onPress,onAdd}:{label:string;value:number;detail:string;color:string;open:boolean;onPress?:()=>void;onAdd?:()=>void}){return <Pressable onPress={onPress} style={[S.budgetHero,{backgroundColor:color}]}><View style={S.flex}><Text style={S.budgetHeroLabel}>{label}</Text><Text style={S.budgetHeroValue}>{kr(value)}/mnd</Text><Text style={S.budgetHeroDetail}>{detail}</Text></View><View style={S.budgetHeroActions}>{onAdd?<Pressable onPress={e=>{e.stopPropagation();onAdd()}} style={S.heroAddButton}><Ionicons name="add" size={28} color={C.white}/></Pressable>:null}{onPress?<Ionicons name={open?'chevron-up':'chevron-down'} size={22} color="#EFE8DD"/>:null}</View></Pressable>}
function GestureBudgetLine({icon,name,sub,value,onPress,onEdit,onDelete}:{icon:Icon;name:string;sub:string;value:number;onPress:()=>void;onEdit:()=>void;onDelete:()=>void}){
  const x=useRef(new Animated.Value(0)).current;const[openSide,setOpenSide]=useState<'edit'|'delete'|null>(null);
  const close=()=>{setOpenSide(null);Animated.spring(x,{toValue:0,useNativeDriver:true}).start()};
  const pan=useRef(PanResponder.create({onMoveShouldSetPanResponder:(_,g)=>Math.abs(g.dx)>12,onPanResponderMove:(_,g)=>x.setValue(Math.max(-105,Math.min(105,g.dx))),onPanResponderRelease:(_,g)=>{if(g.dx>45){setOpenSide('edit');Animated.spring(x,{toValue:96,useNativeDriver:true}).start()}else if(g.dx<-45){setOpenSide('delete');Animated.spring(x,{toValue:-96,useNativeDriver:true}).start()}else close()}})).current;
  const runEdit=()=>{close();onEdit()};const runDelete=()=>{close();onDelete()};
  return <View style={S.gestureWrap}><Pressable onPress={runEdit} style={S.swipeEdit}><Text style={S.swipeActionText}>Rediger</Text></Pressable><Pressable onPress={runDelete} style={S.swipeDelete}><Text style={S.swipeActionText}>Slett</Text></Pressable><Animated.View {...pan.panHandlers} style={{transform:[{translateX:x}]}}><Pressable onPress={openSide?close:onPress} style={[S.budgetLine,S.swipeForeground]}><View style={S.smallIcon}><Ionicons name={icon} size={19} color={C.green}/></View><View style={S.flex}><Text style={S.cardTitle}>{name}</Text>{sub?<Text style={S.cardSub}>{sub}</Text>:null}</View><View style={S.right}><Text style={S.value}>{kr(value)}</Text><Text style={S.per}>per mnd</Text></View><Ionicons name="chevron-forward" size={18} color={C.green}/></Pressable></Animated.View></View>}
function InsuranceView({items,add,del,edit}:{items:Insurance[];add:()=>void;del:(i:string,t:string)=>void;edit:(id:string)=>void}){
  const[selected,setSelected]=useState<Insurance|null>(null);
  return <>
    <Summary k="SAMLET FORSIKRING" a={kr(items.reduce((a,b)=>a+b.monthly,0))+'/mnd'} d={`${items.length} registrerte avtaler`}/>
    <Section title="Mine forsikringer" action="Legg til" onPress={add}/>
    {[...items].sort((a,b)=>b.monthly-a.monthly).map(x=><GestureBudgetLine key={x.id} icon={insIcon(x.type)} name={x.type} sub={`${x.provider} • ${kr(x.monthly)}/mnd`} value={x.monthly} onPress={()=>setSelected(x)} onEdit={()=>edit(x.id)} onDelete={()=>del(x.id,x.type)}/>)}
    <Modal visible={selected!==null} transparent animationType="fade" statusBarTranslucent onRequestClose={()=>setSelected(null)}>
      <View style={S.insuranceModalRoot}>
        <Pressable style={S.insuranceModalBackdrop} onPress={()=>setSelected(null)}/>
        {selected?<View style={S.insuranceModalCard}>
          <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={S.insuranceModalContent}>
            <View style={S.modalHead}>
              <View style={S.flex}><Text style={S.greenKicker}>FORSIKRING</Text><Text style={S.modalTitle}>{selected.type}</Text></View>
              <Pressable onPress={()=>setSelected(null)} style={S.closeCircle}><Ionicons name="close" size={22} color={C.ink}/></Pressable>
            </View>
            <View style={S.insProviderRow}><View style={S.insProviderIcon}><Ionicons name={insIcon(selected.type)} size={22} color={C.green}/></View><View><Text style={S.insEyebrow}>SELSKAP</Text><Text style={S.insProvider}>{selected.provider}</Text></View></View><View style={S.insPricePanel}><View><Text style={S.insEyebrow}>PRIS</Text><Text style={S.insPrice}>{kr(selected.monthly)}<Text style={S.insPriceUnit}>/mnd</Text></Text></View><View style={S.insAnnual}><Text style={S.insAnnualLabel}>Per år</Text><Text style={S.insAnnualValue}>{kr(selected.monthly*12)}</Text></View></View><View style={S.insSection}><Text style={S.insSectionTitle}>Avtalen</Text><InsuranceFact label="Dekning" value={selected.coverage||selected.coverageType||'Ikke registrert'}/><InsuranceFact label="Fornyelse" value={selected.expiryDate||selected.renewal||'Ikke registrert'}/><InsuranceFact label="Egenandel" value={selected.deductible||'Ikke registrert'}/></View><View style={S.insSection}><Text style={S.insSectionTitle}>Flere detaljer</Text><InsuranceFact label="Bonus" value={selected.bonus||'Ikke registrert'}/><InsuranceFact label="Forsikringssum" value={selected.insuredValue||'Ikke registrert'}/><InsuranceFact label="Tegningsdato" value={selected.startDate||'Ikke registrert'}/><InsuranceFact label="Notat" value={selected.note||'Ikke registrert'}/></View><View style={S.insBudgetTag}><Ionicons name="checkmark-circle" size={17} color={C.green}/><Text style={S.insBudgetTagText}>Inkludert i Budsjett</Text></View><View style={S.popupActions}>
              <Pressable onPress={()=>{const id=selected.id;setSelected(null);edit(id)}} style={S.editButton}><Text style={S.editButtonText}>Rediger</Text></Pressable>
              <Pressable onPress={()=>{const current=selected;setSelected(null);del(current.id,current.type)}} style={S.deleteButton}><Text style={S.deleteButtonText}>Slett</Text></Pressable>
            </View>
          </ScrollView>
        </View>:null}
      </View>
    </Modal>
  </>;
}
function InsuranceFact({label,value}:{label:string;value:string}){return <View style={S.insFact}><Text style={S.insFactLabel}>{label}</Text><Text style={S.insFactValue}>{value}</Text></View>}
function Subscriptions({items,add,del,edit}:{items:Subscription[];add:()=>void;del:(i:string,t:string)=>void;edit:(id:string)=>void}){return <><Summary k="LØPENDE ABONNEMENT" a={kr(items.reduce((a,b)=>a+b.monthly,0))+'/mnd'} d={kr(items.reduce((a,b)=>a+b.monthly*12,0))+'/år'}/><Section title="Mine abonnement" action="Legg til" onPress={add}/>{[...items].sort((a,b)=>b.monthly-a.monthly).map(x=><GestureBudgetLine key={x.id} icon={subIcon(`${x.name} ${x.category}`)} name={x.name} sub={`${x.category} • neste ${x.renewal||'ikke registrert'}`} value={x.monthly} onPress={()=>Alert.alert(x.name,`${x.category}\n${kr(x.monthly)} per måned\n${kr(x.monthly*12)} per år\nNeste betaling: ${x.renewal||'ikke registrert'}`)} onEdit={()=>edit(x.id)} onDelete={()=>del(x.id,x.name)}/>)}</>}
function Savings({goals,add,del,edit,update}:{goals:Goal[];add:()=>void;del:(i:string,t:string)=>void;edit:(id:string)=>void;update:(i:string,n:number)=>void}){const groups:GoalCategory[]=['Sparemål','Buffer','Fond','Aksjer','Pensjon'];return <><Summary k="SAMLET SPARING" a={kr(goals.reduce((a,b)=>a+b.saved,0))} d={kr(goals.reduce((a,b)=>a+b.monthly,0))+' fast sparing per måned'}/><Section title="Sparing og investering" action="Legg til" onPress={add}/>{groups.map(c=>{const list=goals.filter(g=>g.category===c).sort((a,b)=>(b.monthly-a.monthly)||(b.saved-a.saved));return list.length?<View key={c}><Text style={S.groupTitle}>{c}</Text>{list.map(g=><GoalCard key={g.id} g={g} del={()=>del(g.id,g.name)} edit={()=>edit(g.id)} update={n=>update(g.id,n)}/>)}</View>:null})}</>}
function GoalCard({g,del,edit,update}:{g:Goal;del:()=>void;edit:()=>void;update:(n:number)=>void}){const[pay,setPay]=useState(Math.max(500,g.monthly||1000));const[showExtra,setShowExtra]=useState(false);const pct=g.target?Math.min(100,Math.round(g.saved/g.target*100)):0;return <View style={S.goal}>{g.imageUri?<ImageBackground source={{uri:g.imageUri}} style={S.goalImage} imageStyle={S.goalImageInner}><View style={S.overlay}/><View style={S.goalText}><Text style={S.goalLight}>{g.name}</Text><Text style={S.goalMeta}>{g.category} • {g.targetDate}</Text></View></ImageBackground>:<View style={S.goalFallback}><Ionicons name={goalIcon(g)} size={32} color={C.green}/><View style={S.flex}><Text style={S.groupTitle}>{g.name}</Text><Text style={S.cardSub}>{g.category} • {g.targetDate}</Text></View></View>}<View style={S.trashFloat}><Pressable onPress={edit} style={S.editMini}><Ionicons name="pencil-outline" size={18} color={C.green}/></Pressable><Trash onPress={del}/></View><View style={S.goalBody}><Text style={S.goalAmount}>{kr(g.saved)} <Text style={S.goalTarget}>av {kr(g.target)}</Text></Text><Progress val={pct}/><Text style={S.cardSub}>{pct}% • fast {kr(g.monthly)}/mnd • inkludert i budsjettet</Text><Pressable onPress={()=>setShowExtra(v=>!v)} style={S.extraToggle}><Text style={S.extraToggleText}>{showExtra?"Skjul ekstra innbetaling":"Legg til ekstra innbetaling"}</Text><Ionicons name={showExtra?"chevron-up":"chevron-down"} size={17} color={C.green}/></Pressable>{showExtra?<View style={S.sliderBox}><View style={S.rowBetween}><Text style={S.cardSub}>Ekstra innbetaling</Text><Text style={S.value}>{kr(pay)}</Text></View><Slider minimumValue={0} maximumValue={10000} step={100} value={pay} onValueChange={setPay} minimumTrackTintColor={C.green} maximumTrackTintColor="#D9E2DD" thumbTintColor={C.green}/><Pressable onPress={()=>{update(pay);setShowExtra(false)}} style={S.primarySmall}><Text style={S.primaryText}>Registrer innbetaling</Text></Pressable></View>:null}</View></View>}
function Form({kind,initial,editing,close,saveInsurance,saveSubscription,saveGoal,saveIncome,saveExpense}:{kind:FormKind;initial?:any;editing:boolean;close:()=>void;saveInsurance:(x:Omit<Insurance,'id'>)=>void;saveSubscription:(x:Omit<Subscription,'id'>)=>void;saveGoal:(x:Omit<Goal,'id'>)=>void;saveIncome:(x:Omit<BudgetItem,'id'>)=>void;saveExpense:(x:Omit<BudgetItem,'id'>)=>void}){
 const[f,setF]=useState<Record<string,string>>({});const[cat,setCat]=useState<GoalCategory>('Sparemål');const[moreInsurance,setMoreInsurance]=useState(false);const[expenseGroup,setExpenseGroup]=useState<string|null>(null);const[incomeGroup,setIncomeGroup]=useState<string|null>(null);
 const incomeTypes:[string,string[]][]=[['Arbeid',['Lønn','Overtid / tillegg','Bonus','Næringsinntekt']],['Familie og ytelser',['Barnetrygd','Kontantstøtte','Foreldrepenger','Barnebidrag']],['Studier',['Stipend','Studielån']],['Trygd og pensjon',['Sykepenger','Dagpenger','Pensjon','NAV / trygd']],['Kapital og eiendom',['Leieinntekt','Renteinntekt','Utbytte']],['Annet',['Annen inntekt']]];
 const expenseTypes:[string,string[]][]=[['Bolig',['Boliglån','Husleie','Strøm','Kommunale avgifter']],['Forsikringer',['Husforsikring','Innboforsikring','Bilforsikring','Reiseforsikring','Livsforsikring','Ulykkesforsikring','Annen forsikring']],['Abonnement',['Mobil','Internett','TV / streaming','Musikk','Skylagring','Programvare','Avis / nyheter','Gaming','Annet abonnement']],['Mat og husholdning',['Mat og dagligvarer','Husholdningsartikler']],['Barn',['Barnehage / SFO','Klær og utstyr','Fritidsaktiviteter']],['Transport',['Billån','Drivstoff / lading','Bom / parkering','Kollektivtransport']],['Gjeld',['Studielån','Kredittkort / lån']],['Helse og fritid',['Medisiner / behandling','Trening','Restaurant / takeaway','Klær og sko']],['Annet',['Gaver','Kjæledyr','Uforutsette utgifter','Annen utgift']]];
 const set=(k:string,v:string)=>setF(x=>({...x,[k]:v}));
 useEffect(()=>{const i=initial||{};setF(kind==='insurance'?{name:i.type||'',provider:i.provider||'',monthly:i.monthly?groupDigits(String(i.monthly)):'',bonus:i.bonus||'',coverageType:i.coverageType||i.coverage||'',insuredValue:i.insuredValue||'',deductible:i.deductible||'',startDate:i.startDate||'',expiryDate:i.expiryDate||i.renewal||'',note:i.note||''}:kind==='subscription'?{name:i.name||'',category:i.category||'',monthly:i.monthly?groupDigits(String(i.monthly)):'',date:i.renewal||''}:kind==='goal'?{name:i.name||'',monthly:i.monthly?groupDigits(String(i.monthly)):'',target:i.target?groupDigits(String(i.target)):'',saved:i.saved?groupDigits(String(i.saved)):'',date:i.targetDate||''}:kind==='income'?{category:i.category||'',origin:i.origin||'',monthly:i.monthly?groupDigits(String(i.monthly)):''}:kind==='expense'?{name:i.name||'',category:i.category||'',monthly:i.monthly?groupDigits(String(i.monthly)):'',interest:i.interest?groupDigits(String(i.interest)):'',principal:i.principal?groupDigits(String(i.principal)):''}:{});setCat(i.category||'Sparemål');setMoreInsurance(!!(i.bonus||i.coverageType||i.insuredValue||i.deductible||i.startDate||i.expiryDate||i.note));setExpenseGroup(kind==='expense'&&i.category?i.category:null);setIncomeGroup(kind==='income'&&i.category?(incomeTypes.find(([,items])=>items.includes(i.category))?.[0]||null):null)},[kind,initial]);
 if(!kind)return null;
 const submit=()=>{if(kind==='insurance')return saveInsurance({type:f.name||'Forsikring',provider:f.provider||'Ikke registrert',monthly:num(f.monthly),coverage:f.coverageType||'',renewal:f.expiryDate||'',bonus:f.bonus,coverageType:f.coverageType,insuredValue:f.insuredValue,deductible:f.deductible,startDate:f.startDate,expiryDate:f.expiryDate,note:f.note});if(kind==='subscription')return saveSubscription({name:f.name||'Abonnement',category:f.category||'Annet',monthly:num(f.monthly),renewal:f.date||''});if(kind==='goal')return saveGoal({name:f.name||cat,target:num(f.target),saved:num(f.saved),targetDate:f.date||'',category:cat,monthly:num(f.monthly)});if(kind==='income')return saveIncome({name:f.category||'Inntekt',category:f.category||'Annen inntekt',monthly:num(f.monthly),origin:f.origin||undefined});return saveExpense({name:f.name||'Utgift',category:f.category||'Annet',monthly:num(f.monthly),interest:f.name==='Boliglån'?num(f.interest):undefined,principal:f.name==='Boliglån'?num(f.principal):undefined})};
 const title=kind==='insurance'?'forsikring':kind==='subscription'?'abonnement':kind==='goal'?'sparing':kind==='income'?'inntekt':'utgift';
 return <Modal visible transparent animationType="slide"><KeyboardAvoidingView style={S.modalWrap} behavior={Platform.OS==='ios'?'padding':undefined}><Pressable style={S.backdrop} onPress={close}/><View style={S.modal}><View style={S.modalHead}><Text style={S.modalTitle}>{editing?'Rediger':'Legg til'} {title}</Text><Pressable onPress={close}><Ionicons name="close" size={24}/></Pressable></View><ScrollView keyboardShouldPersistTaps="handled">
 {kind==='income'?<><Text style={S.formLabel}>Inntektstype</Text>{!incomeGroup?<View style={S.categoryGrid}>{incomeTypes.map(([group])=><Pressable key={group} onPress={()=>setIncomeGroup(group)} style={S.categoryChoice}><Text style={S.categoryChoiceText}>{group}</Text></Pressable>)}</View>:<><Pressable onPress={()=>setIncomeGroup(null)} style={S.categoryBack}><Ionicons name="chevron-back" size={18} color={C.green}/><Text style={S.categoryBackText}>Alle kategorier</Text></Pressable><Text style={S.expenseSelectedTitle}>{incomeGroup}</Text><View style={S.expenseOptionList}>{(incomeTypes.find(([g])=>g===incomeGroup)?.[1]||[]).map(t=><Pressable key={t} onPress={()=>set('category',/^Annen|^Annet/i.test(t)?'':t)} style={[S.expenseOption,f.category===t&&S.expenseOptionOn]}><Text style={[S.expenseOptionText,f.category===t&&S.expenseOptionTextOn]}>{t}</Text>{f.category===t?<Ionicons name="checkmark" size={20} color={C.white}/>:null}</Pressable>)}</View></>}{incomeGroup==='Annet'?<TextInput value={f.category||''} onChangeText={v=>set('category',v)} placeholder="Skriv egen inntektstype" style={S.input}/>:null}<TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder="Beløp per måned" keyboardType="number-pad" style={S.input}/><TextInput value={f.origin||''} onChangeText={v=>set('origin',v)} placeholder="Utbetaler eller kilde (valgfritt)" style={S.input}/></>:null}
 {kind==='expense'?<><Text style={S.formLabel}>Utgiftstype</Text>{!expenseGroup?<View style={S.categoryGrid}>{expenseTypes.map(([group])=><Pressable key={group} onPress={()=>setExpenseGroup(group)} style={S.categoryChoice}><View style={S.categoryIcon}><Ionicons name={group==='Bolig'?'home-outline':group==='Forsikringer'?'shield-checkmark-outline':group==='Abonnement'?'repeat-outline':group==='Mat og husholdning'?'basket-outline':group==='Barn'?'people-outline':group==='Transport'?'car-outline':group==='Gjeld'?'card-outline':group==='Helse og fritid'?'heart-outline':'ellipsis-horizontal-outline'} size={18} color={C.green}/></View><Text style={S.categoryChoiceText}>{group}</Text></Pressable>)}</View>:<><Pressable onPress={()=>setExpenseGroup(null)} style={S.categoryBack}><Ionicons name="chevron-back" size={18} color={C.green}/><Text style={S.categoryBackText}>Alle kategorier</Text></Pressable><Text style={S.expenseSelectedTitle}>{expenseGroup}</Text><View style={S.expenseOptionList}>{(expenseTypes.find(([g])=>g===expenseGroup)?.[1]||[]).map(t=><Pressable key={t} onPress={()=>setF(x=>({...x,name:/^Annen|^Annet/i.test(t)?'':t,category:expenseGroup}))} style={[S.expenseOption,f.name===t&&S.expenseOptionOn]}><Text style={[S.expenseOptionText,f.name===t&&S.expenseOptionTextOn]}>{t}</Text>{f.name===t?<Ionicons name="checkmark" size={20} color={C.white}/>:null}</Pressable>)}</View></>}{f.name==='Boliglån'?<View style={S.mortgageBox}><Text style={S.formLabel}>Fordel boliglånet</Text><TextInput value={f.interest||''} onChangeText={v=>set('interest',groupDigits(v))} placeholder="Renter per måned" keyboardType="number-pad" style={S.input}/><TextInput value={f.principal||''} onChangeText={v=>set('principal',groupDigits(v))} placeholder="Avdrag per måned" keyboardType="number-pad" style={S.input}/><Text style={S.mortgageTotal}>Sum: {kr(num(f.interest)+num(f.principal))}/mnd</Text></View>:null}<TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder={expenseGroup&&f.name===''?"Skriv egen utgiftstype":"Eget navn (valgfritt)"} style={S.input}/><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder={f.name==='Boliglån'?"Total termin per måned":"Beløp per måned"} keyboardType="number-pad" style={S.input}/></>:null}
 {kind==='insurance'?<><TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder="Type forsikring" style={S.input}/><TextInput value={f.provider||''} onChangeText={v=>set('provider',v)} placeholder="Forsikringsselskap" style={S.input}/><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder="Kostnad per måned" keyboardType="number-pad" style={S.input}/><Pressable onPress={()=>setMoreInsurance(v=>!v)} style={S.moreButton}><Text style={S.moreButtonText}>{moreInsurance?'Skjul detaljer':'Flere detaljer'}</Text></Pressable>{moreInsurance?<><TextInput value={f.bonus||''} onChangeText={v=>set('bonus',v)} placeholder="Bonus" style={S.input}/><TextInput value={f.coverageType||''} onChangeText={v=>set('coverageType',v)} placeholder="Dekningstype" style={S.input}/><TextInput value={f.insuredValue||''} onChangeText={v=>set('insuredValue',groupDigits(v))} placeholder="Forsikringssum" keyboardType="number-pad" style={S.input}/><TextInput value={f.deductible||''} onChangeText={v=>set('deductible',groupDigits(v))} placeholder="Egenandel" keyboardType="number-pad" style={S.input}/><TextInput value={f.startDate||''} onChangeText={v=>set('startDate',v)} placeholder="Tegningsdato" style={S.input}/><TextInput value={f.expiryDate||''} onChangeText={v=>set('expiryDate',v)} placeholder="Utløps-/fornyelsesdato" style={S.input}/><TextInput value={f.note||''} onChangeText={v=>set('note',v)} placeholder="Notat" style={S.input}/></>:null}</>:null}
 {kind==='subscription'?<><TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder="Navn" style={S.input}/><TextInput value={f.category||''} onChangeText={v=>set('category',v)} placeholder="Kategori" style={S.input}/><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder="Beløp per måned" keyboardType="number-pad" style={S.input}/><TextInput value={f.date||''} onChangeText={v=>set('date',v)} placeholder="Neste betaling" style={S.input}/></>:null}
 {kind==='goal'?<><Text style={S.formLabel}>Type sparing</Text><View style={S.chips}>{(['Sparemål','Buffer','Fond','Aksjer','Pensjon'] as GoalCategory[]).map(x=><Pressable key={x} onPress={()=>setCat(x)} style={[S.chip,cat===x&&S.chipOn]}><Text style={[S.chipText,cat===x&&S.chipTextOn]}>{x}</Text></Pressable>)}</View><TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder="Navn" style={S.input}/><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder="Fast månedlig sparing" keyboardType="number-pad" style={S.input}/><TextInput value={f.target||''} onChangeText={v=>set('target',groupDigits(v))} placeholder="Målbeløp" keyboardType="number-pad" style={S.input}/><TextInput value={f.saved||''} onChangeText={v=>set('saved',groupDigits(v))} placeholder="Allerede spart" keyboardType="number-pad" style={S.input}/><TextInput value={f.date||''} onChangeText={v=>set('date',v)} placeholder="Måldato" style={S.input}/></>:null}
 <Pressable onPress={submit} style={S.primary}><Text style={S.primaryText}>{editing?'Lagre endringer':'Lagre'}</Text></Pressable></ScrollView></View></KeyboardAvoidingView></Modal>}

function Nav({active,go}:{active:Tab;go:(t:Tab)=>void}){return <View style={S.nav}>{tabs.map(x=><Pressable key={x.name} onPress={()=>go(x.name)} style={[S.navItem,active===x.name&&S.navItemOn]}><Ionicons name={x.icon} size={21} color={active===x.name?C.green:C.muted}/><Text numberOfLines={1} style={[S.navText,active===x.name&&S.navOn]}>{x.name}</Text></Pressable>)}</View>}
function MonthMetric({icon,label,value}:{icon:Icon;label:string;value:string}){return <View style={S.monthMetric}><View style={S.monthMetricIcon}><Ionicons name={icon} size={19} color={C.green}/></View><Text style={S.monthMetricLabel}>{label}</Text><Text style={S.monthMetricValue}>{value}</Text></View>}
function Tile({icon,title,value,sub,onPress}:{icon:Icon;title:string;value:string;sub:string;onPress:()=>void}){return <Pressable onPress={onPress} style={S.tile}><View style={S.icon}><Ionicons name={icon} size={22} color={C.green}/></View><View style={S.flex}><Text style={S.cardTitle}>{title}</Text><Text style={S.cardSub}>{sub}</Text></View><Text style={S.value}>{value}</Text></Pressable>}
function Section({title,action,onPress}:{title:string;action?:string;onPress?:()=>void}){return <View style={S.section}><Text style={S.sectionTitle}>{title}</Text>{action&&<Pressable onPress={onPress} style={S.add}><Ionicons name="add" size={18} color={C.green}/><Text style={S.addText}>{action}</Text></Pressable>}</View>}
function Summary({k,a,d}:{k:string;a:string;d:string}){return <View style={S.summary}><Text style={S.kicker}>{k}</Text><Text style={S.summaryAmount}>{a}</Text><Text style={S.summaryText}>{d}</Text></View>}
function Detail({l,v}:{l:string;v:string}){return <View style={S.detail}><Text style={S.detailLabel}>{l}</Text><Text style={S.detailValue}>{v}</Text></View>}
function Trash({onPress}:{onPress:()=>void}){return <Pressable onPress={onPress} style={S.trash}><Ionicons name="trash-outline" size={18} color={C.red}/></Pressable>}
function Progress({val}:{val:number}){return <View style={S.track}><View style={[S.fill,{width:`${Math.min(100,val)}%`}]}/></View>}
